    11	export const runtime = "nodejs";
    12	
    13	/**
    14	 * Page-view capture endpoint. Called fire-and-forget by <VisitTracker/> mounted
    15	 * in the marketing layout and the portal Shell. It records a single `Visit` row
    16	 * and MUST NOT throw or block the caller — analytics is strictly best-effort.
    17	 *
    18	 * The client IP is the PROXY-ATTESTED address (`trustedClientIp`); we never
    19	 * trust a body-supplied IP, nor the first hop of `X-Forwarded-For` — nginx
    20	 * appends to that header, so its first entry is caller-chosen. That mattered
    21	 * twice here: it was the rate-limit key (so one header defeated the 60/min cap
    22	 * on durable row insertion), and it is PERSISTED to `Visit.ip`, which is what
    23	 * the admin visitors/analytics pages attribute traffic and abuse to. A forged
    24	 * value poisoned both.
    25	 *
    26	 * Bots are CLASSIFIED, not dropped (2026-10-01, lib/bots/classify.ts): the row
    27	 * is stored with `isBot`/`botKind`/`botReason` so every analytics read can
    28	 * exclude it by default (and the admin can still see it with "include bots"),
    29	 * and the worker re-classifier (worker/bot-classify.ts) can upgrade a verdict
    30	 * later from behaviour. Before this, a coarse UA regex silently dropped
    31	 * self-declared bots but let headless scrapers (Lightpanda, ~3k rows/day from
    32	 * residential proxies) and stale-UA fleets straight into the human numbers.
    33	 * The visit "kind" (marketing vs portal) comes from a `?k=` query param the
    34	 * mounter sets.
    35	 *
    36	 * Two shapes of POST arrive here:
    37	 *  - a PAGEVIEW (has `path`): inserts the Visit row, attaches session/pvid/utm and
    38	 *    a stable, consent-gated `visitorId` (see below).
    39	 *  - a CLOSE beacon (`{ close, pvid, dur }`, often via navigator.sendBeacon on
    40	 *    pagehide): stamps the dwell time onto the earlier row with that pvid. This is
    41	 *    what makes "avg time on site" and bounce rate possible.
    42	 *
    43	 * Stable visitor id (recurring vs new): we keep a first-party `nx_vid` cookie and
    44	 * persist it on each Visit, so a returning person is recognisable across sessions
    45	 * without any third party. It is CONSENT-GATED to the site's own opt-out model
    46	 * (lib/consent.ts): only minted/persisted unless the visitor explicitly chose
    47	 * "necessary" (nxeon_cookie_consent=necessary), in which case visitorId stays null
    48	 * and that person is only ever counted by the coarse IP path.
    49	 */
    50	
    51	const VID_COOKIE = "nx_vid";
    52	const VID_MAX_AGE = 60 * 60 * 24 * 365; // 1 year
    53	const CONSENT_COOKIE = "nxeon_cookie_consent";
    54	
    55	/** Read one cookie value out of the raw Cookie header. */
    56	function readCookie(req: Request, name: string): string | null {
    57	  const raw = req.headers.get("cookie");
    58	  if (!raw) return null;
    59	  for (const part of raw.split("; ")) {
    60	    if (part.startsWith(`${name}=`)) return part.slice(name.length + 1);
    61	  }
    62	  return null;
    63	}
    64	
    65	/** Clamp a client-supplied opaque id to something sane before it hits the DB. */
    66	function cleanId(v: unknown): string | null {
    67	  if (typeof v !== "string") return null;
    68	  const s = v.trim();
    69	  if (!s || s.length > 64 || !/^[A-Za-z0-9._-]+$/.test(s)) return null;
    70	  return s;
    71	}
    72	
    73	function cleanUtm(v: unknown): string | null {
    74	  if (typeof v !== "string") return null;
    75	  const s = v.trim().slice(0, 120);
    76	  return s || null;
    77	}
