    82	    // per-IP to cap unbounded row insertion. Over the limit: silent no-op.
    83	    const ip = trustedClientIp(req);
    84	    const rl = checkRateLimit(`track:${ip}`, { max: 120, windowMs: 60_000 });
    85	    if (!rl.ok) {
    86	      return new NextResponse(null, { status: 204 });
    87	    }
