   178	    // indistinguishable from the customer's real, older sign-ins (found live
   179	    // 2026-09-25). This isn't a session or a sign-in at all, so there's no
   180	    // correct non-null attribution to fall back to -- the admin's access is
   181	    // already recorded, correctly attributed, by the `admin.impersonate_start`
   182	    // AuditLog entry (lib/actions-account.ts's `impersonateUser`); this
   183	    // endpoint's job is the customer's own real browsing history, so it must
   184	    // simply skip attribution for the duration of the impersonation grant.
   185	    let userId: string | null = null;
   186	    try {
   187	      const imp = await impersonating();
   188	      userId = imp ? null : ((await currentUser())?.id ?? null);
   189	    } catch {
