   203	    let utmMedium = cleanUtm(body.utmMedium);
   204	    if (gclid && !utmSource) {
   205	      utmSource = "google";
   206	      utmMedium = utmMedium ?? "cpc";
   207	    }
   208	
   209	    // --- Bot classification at ingest (cheap, local: UA catalogue, official
   210	    // crawler IP lists, datacenter ranges, one indexed BotIpFlag lookup). No
   211	    // DNS here — FCrDNS verification happens asynchronously in the worker.
   212	    const webdriver = body.wd === true ? true : body.wd === false ? false : null;
   213	    const ipFlag = await activeIpFlag(ip);
   214	    const bot = classifyHit({ ua, ip, userId, webdriver, ipFlag });
