   216	      // Self-declared crawlers rendering JS can fire this beacon for every page
   217	      // they crawl; cap their rows globally per crawler so a crawl of 65k pages
   218	      // can't balloon the Visit table (crawler volume is measured from the
   219	      // access log instead — worker/crawler-log.ts).
   220	      const cap = checkRateLimit(`trackbot:${bot.crawlerId}`, { max: 300, windowMs: 60_000 });
   221	      if (!cap.ok) return NextResponse.json({ ok: true });
   222	    }
   223	
   224	    await db.visit.create({
   225	      data: {
   226	        ip,
   227	        path,
   228	        referrer,
   229	        ua,
   230	        deviceType,
   231	        os,
   232	        browser,
   233	        kind,
   234	        userId,
   235	        visitorId,
   236	        sessionId: cleanId(body.sessionId),
   237	        pvid: cleanId(body.pvid),
   238	        isEntry: body.isEntry === true,
   239	        utmSource,
   240	        utmMedium,
   241	        utmCampaign: cleanUtm(body.utmCampaign),
   242	        gclid,
   243	        isBot: bot.isBot,
   244	        botKind: bot.botKind,
   245	        botReason: bot.botReason,
   246	        webdriver,
   247	      },
   248	    });
