   252	      res.cookies.set(VID_COOKIE, setVidCookie, {
   253	        httpOnly: true,
   254	        sameSite: "lax",
   255	        secure: true,
   256	        path: "/",
   257	        maxAge: VID_MAX_AGE,
   258	      });
   259	    }
   260	    return res;
   261	  } catch {
   262	    // Never surface capture failures to the page.
   263	  }
   264	  return NextResponse.json({ ok: true });
   265	}
