     3	import { useEffect, useRef } from "react";
     4	import { usePathname } from "next/navigation";
     5	
     6	/**
     7	 * Invisible page-view beacon. Mount once in the marketing layout (kind default)
     8	 * and once in the portal Shell with `kind="portal"`. On every client-side route
     9	 * change it fires a best-effort POST to /api/track. Rapid repeats of the same
    10	 * path are de-duped within the tab via sessionStorage so React strict-mode
    11	 * double-mounts and quick back/forward navigation don't double-count.
    12	 *
    13	 * Beyond the raw pageview it now also captures the behaviour the audience/funnel
    14	 * dashboard needs, all client-side and cookie-free here (the durable, consent-gated
    15	 * visitor id is minted server-side in /api/track):
    16	 *  - a per-TAB `sessionId` (sessionStorage, restarts after 30 min idle) so pageviews
    17	 *    group into sessions for "avg time on site" and bounce rate,
    18	 *  - an `isEntry` flag on the first pageview of a session (the landing page),
    19	 *  - `utm_*` params off the landing URL, remembered for the whole session so every
    20	 *    page attributes back to the ad/campaign that brought the visitor,
    21	 *  - a per-pageview id (`pvid`) plus a dwell-time "close" beacon fired on navigation
    22	 *    away and on pagehide, so each pageview gets a real time-on-page.
    23	 *
    24	 * Bot-detection signals (2026-10-01, lib/bots/*): `wd` = navigator.webdriver on the
    25	 * pageview, `ix` = whether any real input event (pointer/scroll/key/touch) happened
    26	 * before the close beacon, and an invisible honeypot link to a robots-disallowed
    27	 * path (/api/track/hp) that only link-harvesting scrapers ever follow.
    28	 */
    29	export default function VisitTracker({ kind = "marketing" }: { kind?: "marketing" | "portal" }) {
    30	  const pathname = usePathname();
    31	  // The currently-open pageview whose dwell time we still owe a close beacon for.
    32	  const openRef = useRef<{ pvid: string; start: number } | null>(null);
    33	  // Any genuine input on the current pageview (reset per pageview).
    34	  const interactedRef = useRef(false);
    35	
    36	  useEffect(() => {
    37	    if (typeof window === "undefined") return;
    38	    const mark = () => {
    39	      interactedRef.current = true;
    40	    };
    41	    const evs = ["pointerdown", "pointermove", "keydown", "scroll", "touchstart", "wheel"] as const;
    42	    for (const e of evs) window.addEventListener(e, mark, { passive: true, capture: true });
    43	    return () => {
    44	      for (const e of evs) window.removeEventListener(e, mark, { capture: true });
    45	    };
    46	  }, []);
    47	
    48	  useEffect(() => {
    49	    if (typeof window === "undefined") return;
    50	    const path = pathname || window.location.pathname || "/";
    51	
    52	    // Dedupe: skip if we already tracked this exact path within the last 30s.
    53	    const dkey = `nx_track:${kind}:${path}`;
    54	    try {
    55	      const last = Number(window.sessionStorage.getItem(dkey) ?? 0);
    56	      if (Date.now() - last < 30_000) return;
    57	      window.sessionStorage.setItem(dkey, String(Date.now()));
    58	    } catch {
    59	      /* private mode / storage disabled — just proceed without dedupe */
    60	    }
    61	
    62	    // --- Session id (per tab, 30-min idle window) + entry detection ---
    63	    const SESSION_IDLE_MS = 30 * 60_000;
    64	    let sessionId = "";
    65	    let isEntry = false;
    66	    let utm: { source?: string; medium?: string; campaign?: string; gclid?: string } = {};
    67	    try {
    68	      const now = Date.now();
    69	      const prevId = window.sessionStorage.getItem("nx_sid");
    70	      const prevTs = Number(window.sessionStorage.getItem("nx_sid_ts") ?? 0);
    71	      if (prevId && now - prevTs < SESSION_IDLE_MS) {
    72	        sessionId = prevId;
    73	        // Carry the session's captured campaign forward to every page.
    74	        try {
    75	          utm = JSON.parse(window.sessionStorage.getItem("nx_utm") ?? "{}");
    76	        } catch {
    77	          /* ignore malformed */
    78	        }
    79	      } else {
    80	        // Fresh session: this pageview is the entry/landing hit.
    81	        sessionId = genId();
    82	        isEntry = true;
    83	        const qs = new URLSearchParams(window.location.search);
    84	        const src = qs.get("utm_source") ?? undefined;
    85	        const med = qs.get("utm_medium") ?? undefined;
    86	        const camp = qs.get("utm_campaign") ?? undefined;
    87	        // Google Ads click id. Auto-tagging appends `?gclid=…` with no utm params,
    88	        // so without this those clicks would land unattributed. Fall back to Google's
    89	        // own first-party `_gcl_aw` cookie (`GCL.<ts>.<gclid>`) when the URL has none.
    90	        const gclid = qs.get("gclid") ?? readGclAw() ?? undefined;
    91	        utm = {
    92	          ...(src ? { source: src.slice(0, 120) } : {}),
    93	          ...(med ? { medium: med.slice(0, 120) } : {}),
    94	          ...(camp ? { campaign: camp.slice(0, 120) } : {}),
    95	          ...(gclid ? { gclid: gclid.slice(0, 200) } : {}),
    96	        };
    97	        window.sessionStorage.setItem("nx_sid", sessionId);
    98	        window.sessionStorage.setItem("nx_utm", JSON.stringify(utm));
    99	      }
   100	      window.sessionStorage.setItem("nx_sid_ts", String(now));
   101	    } catch {
   102	      // Storage disabled — still track the pageview, just without session grouping.
   103	      sessionId = genId();
   104	    }
   105	
   106	    // Close out the previous pageview's dwell before opening this one (SPA nav).
   107	    closeOpen();
   108	
   109	    const pvid = genId();
   110	    openRef.current = { pvid, start: Date.now() };
   111	    interactedRef.current = false;
   112	    let wd: boolean | null = null;
   113	    try {
   114	      wd = navigator.webdriver === true;
   115	    } catch {
   116	      /* ignore */
   117	    }
   118	
   119	    try {
   120	      fetch(`/api/track?k=${kind}`, {
   121	        method: "POST",
   122	        headers: { "content-type": "application/json" },
   123	        body: JSON.stringify({
   124	          path,
   125	          referrer: document.referrer || null,
   126	          sessionId,
   127	          pvid,
   128	          isEntry,
   129	          utmSource: utm.source ?? null,
   130	          utmMedium: utm.medium ?? null,
   131	          utmCampaign: utm.campaign ?? null,
   132	          gclid: utm.gclid ?? null,
   133	          wd,
   134	        }),
   135	        keepalive: true,
   136	      }).catch(() => {});
   137	    } catch {
   138	      /* fire-and-forget; never disrupt the page */
   139	    }
   140	    // pathname is the dependency; helpers are stable closures.
   141	    // eslint-disable-next-line react-hooks/exhaustive-deps
   142	  }, [pathname, kind]);
   143	
   144	  // Close the last open pageview when the tab is actually going away.
   145	  useEffect(() => {
   146	    if (typeof window === "undefined") return;
   147	    const onHide = () => closeOpen();
   148	    const onVis = () => {
   149	      if (document.visibilityState === "hidden") closeOpen();
   150	    };
   151	    window.addEventListener("pagehide", onHide);
   152	    document.addEventListener("visibilitychange", onVis);
   153	    return () => {
   154	      window.removeEventListener("pagehide", onHide);
   155	      document.removeEventListener("visibilitychange", onVis);
   156	    };
   157	    // eslint-disable-next-line react-hooks/exhaustive-deps
   158	  }, [kind]);
   159	
   160	  /** Send the dwell time for the currently-open pageview, once. */
   161	  function closeOpen() {
   162	    const open = openRef.current;
   163	    if (!open) return;
   164	    openRef.current = null;
   165	    const dur = Date.now() - open.start;
   166	    if (dur < 250) return; // ignore instant bounces / strict-mode churn
   167	    const body = JSON.stringify({ close: true, pvid: open.pvid, dur, ix: interactedRef.current });
   168	    try {
   169	      // sendBeacon survives unload; fall back to keepalive fetch.
   170	      if (navigator.sendBeacon) {
   171	        navigator.sendBeacon(`/api/track?k=${kind}`, new Blob([body], { type: "application/json" }));
   172	      } else {
   173	        fetch(`/api/track?k=${kind}`, {
   174	          method: "POST",
   175	          headers: { "content-type": "application/json" },
   176	          body,
   177	          keepalive: true,
   178	        }).catch(() => {});
   179	      }
   180	    } catch {
   181	      /* best-effort */
   182	    }
   183	  }
   184	
   185	  // Honeypot: invisible to people (off-screen, aria-hidden, untabbable) and to
   186	  // well-behaved crawlers (/api is Disallowed in app/robots.ts, and the link is
   187	  // nofollow). Only scrapers that harvest every <a href> fetch it, and
   188	  // app/api/track/hp/route.ts flags the fetching IP.
   189	  return (
   190	    <a
   191	      href="/api/track/hp"
   192	      rel="nofollow"
   193	      tabIndex={-1}
   194	      aria-hidden="true"
   195	      style={{ position: "absolute", left: "-10000px", top: "auto", width: 1, height: 1, overflow: "hidden" }}
   196	    >
   197	      &#8203;
   198	    </a>
   199	  );
   200	}
   201	
   202	/** Read the gclid out of Google's `_gcl_aw` cookie (`GCL.<ts>.<gclid>`), if present.
   203	 *  Used as a fallback when the current URL carries no `?gclid=` — e.g. the visitor
   204	 *  clicked the ad, gtag stored the cookie, then navigated deeper before we tracked. */
   205	function readGclAw(): string | undefined {
   206	  try {
   207	    const m = document.cookie.match(/(?:^|;\s*)_gcl_aw=([^;]+)/);
   208	    if (!m) return undefined;
   209	    const parts = decodeURIComponent(m[1]).split(".");
   210	    const id = parts[parts.length - 1];
   211	    return id && id.length > 3 ? id : undefined;
   212	  } catch {
   213	    return undefined;
   214	  }
   215	}
   216	
   217	/** Small random id; prefers crypto.randomUUID, falls back for old browsers. */
   218	function genId(): string {
   219	  try {
   220	    if (typeof crypto !== "undefined" && crypto.randomUUID) return crypto.randomUUID();
   221	  } catch {
   222	    /* ignore */
   223	  }
