const ICON_BY_FAMILY: Record<string, string> = {
  ubuntu: "ubuntu", debian: "debian", almalinux: "osA", rocky: "osC",
  arch: "arch", fedora: "osB", windows: "windows", centos: "osA",
  docker: "docker", wordpress: "cloud", node: "nginx", nginx: "nginx",
  mysql: "mysql", postgres: "postgres", redis: "redis",
