  cloudpanel: "sliders", cyberpanel: "sliders", aapanel: "sliders",
};
function osIcon(family: string, category: string): string {
  return ICON_BY_FAMILY[family?.toLowerCase()]
    ?? (category === "CONTROL_PANEL" ? "sliders" : category === "APPLICATION" ? "cube" : "linux");
}

