export async function DeployPageContent({ user: signedIn }: { user: DeployPageUser | null }) {
  const guest = signedIn === null;
  // Which Stripe local methods the Payment step may offer. Fail closed: any error means none.
  const localMethods = guest
    ? []
    : await enabledLocalMethods()
        .then((ms) => ms.map((m) => ({ id: m.id as string, label: m.label, note: m.note, currency: m.chargeCurrency })))
        .catch(() => []);
  // Never dereferenced for a guest: every use below is guarded on `guest`.
  const user: DeployPageUser = signedIn ?? { id: "", name: "", balanceCents: 0 };
