import "server-only";
import { cache } from "react";
import { Prisma } from "@prisma/client";
import { db } from "@/lib/db";
import { geoLocateIp } from "@/lib/geo-ip";
import { evaluateRisk, emailFamilyKey, parseFlagNote, type RiskFacts, type RiskReport } from "@/lib/admin-client/risk";

/** The customer row every tab of /admin/users/[id] starts from (deduped by React cache). */
export const loadClientCore = cache(async (id: string) => {
  return db.user.findUnique({
    where: { id },
    include: {
      customerNotes: { include: { author: { select: { name: true, email: true } } }, orderBy: { createdAt: "desc" } },
      _count: {
        select: { servers: true, sshKeys: true, notifications: true, hostingAccounts: true, emailSubscriptions: true, domains: true, invoices: true, apiTokens: true, tickets: true, paymentCards: true },
      },
    },
  });
});
export type ClientCore = NonNullable<Awaited<ReturnType<typeof loadClientCore>>>;

export function clientFlags(c: ClientCore) {
  return c.customerNotes
    .map((n) => ({ note: n, flag: parseFlagNote(n.body) }))
    .filter((x): x is { note: (typeof c.customerNotes)[number]; flag: NonNullable<ReturnType<typeof parseFlagNote>> } => !!x.flag);
}

const DAY = 86_400_000;

/**
 * Gather the facts lib/admin-client/risk.ts scores. Everything is a bounded
 * read (indexed columns, LIMITs), so the profile tab stays fast on old
 * accounts with thousands of visits.
 */
export const loadRisk = cache(async (c: ClientCore): Promise<{ report: RiskReport; facts: RiskFacts }> => {
  const [visits, sessions, cards, invoices, abuse, archives, fraudAudits] = await Promise.all([
    db.visit.findMany({ where: { userId: c.id }, orderBy: { createdAt: "desc" }, take: 500, select: { ip: true, country: true, visitorId: true } }),
