    db.paymentCard.findMany({ where: { userId: c.id }, select: { createdAt: true, unusableAt: true } }),
    db.invoice.findMany({ where: { userId: c.id }, select: { number: true, status: true, amountCents: true, refundedCents: true, createdAt: true, paidAt: true } }),

