const CLIENT_ACK_ERROR = "Players need this mod too. Confirm that you will tell them before installing.";

async function act(serverId: string, modId: string, op: ModOp, opts?: { ackClient?: boolean }): Promise<{ ok?: true; error?: string; jobId?: string }> {
  const { user, server, family } = await ownedServer(serverId);
  if (!family) return { error: "This server doesn't support mods." };
  if (server.status !== "RUNNING") return { error: "Start the server's VM first — mods are installed onto the running server." };
  const mod = await db.gameMod.findUnique({ where: { id: String(modId) } });
  if (!mod) return { error: "That mod is unavailable." };
  if (mod.gameFamily !== family) return { error: "That mod isn't for this game." };
  if (op === "install") {
    if (!mod.active || !mod.upstreamOk) return { error: "That mod is no longer available upstream." };
    const sup = installSupport(family, mod.source);
    if (!sup.ok) return { error: sup.message };
    const c = compatFor(family, mod, serverFacts(server, family));
    if (c.verdict === "unsupported") return { error: c.detail };
    // A mod every player must also install is only installed once the owner has
    // seen the warning (the install dialog sends ackClient). Direct callers that
    // skip the dialog get the same message instead of a silent lock-out.
    if (clientWarningFor(mod, server.gameVariant ?? null).required === true && !opts?.ackClient) return { error: CLIENT_ACK_ERROR };
  }
  if ((op === "update" || op === "disable" || op === "enable") && !engineInstallerFor(family, mod.source)) {
    return { error: "That action isn't available for this game yet." };
  }
  const r = await enqueueModOp(serverId, mod.id, op, { userId: user.id, slug: mod.slug });
  if (!r.ok) return { error: r.error };
  revalidatePath(`/dashboard/servers/${serverId}`);
  return { ok: true, jobId: r.jobId };
}

