/**
 * How long an `EmailLog` row is kept. There was no retention at all: every
 * message ever sent was kept forever, which is what turned a rendering-preview
 * convenience into an indefinite archive of customer correspondence. 90 days is
 * long enough to debug a deliverability complaint and short enough that the log
 * is not a second copy of the customer database.
 */
export function emailLogRetentionDays(): number {
  const raw = Number(process.env.NXEON_EMAIL_LOG_RETENTION_DAYS ?? 90);
  if (!Number.isFinite(raw) || raw <= 0) return 90;
  return Math.min(Math.max(Math.floor(raw), 1), 3650);
}

/** The instant before which `EmailLog` rows are deleted, given `now`. */
export function emailLogCutoff(now: number = Date.now()): Date {
  return new Date(now - emailLogRetentionDays() * 24 * 60 * 60 * 1000);
}

/**
 * Opportunistic retention sweep — at most once an hour, never blocking a send,
 * never throwing. Same shape as the bucket sweep in lib/rate-limit.ts: no timer,
 * no cron row to forget to schedule, and it runs on the only event that can grow
 * the table.
 */
let lastPrune = 0;
const PRUNE_INTERVAL_MS = 60 * 60_000;
async function pruneEmailLog(now: number): Promise<void> {
  if (now - lastPrune < PRUNE_INTERVAL_MS) return;
  lastPrune = now;
  try {
    await (await prisma()).emailLog.deleteMany({
      where: { createdAt: { lt: emailLogCutoff(now) } },
    });
  } catch (e) {
    console.error("[email-render] EmailLog retention sweep failed:", e);
  }
}

