export const CONSENT_COOKIE = "nxeon_cookie_consent";
export const CONSENT_MAX_AGE = 60 * 60 * 24 * 365;

/** Fired on `window` when a visitor accepts or declines, so widgets re-measure. */
export const CONSENT_EVENT = "nxeon:cookie-consent";

/** True once the visitor has chosen. SSR-safe: assumes chosen, so nothing moves. */
export function hasCookieConsent(): boolean {
  if (typeof document === "undefined") return true;
  try {
    return document.cookie.split("; ").some((c) => c.startsWith(`${CONSENT_COOKIE}=`));
  } catch {
    // Cookies blocked entirely — treat as decided so we never pin a banner-shaped
    // hole in the corner of a page whose banner will never appear.
    return true;
  }
}

export function setCookieConsent(value: "all" | "necessary") {
  document.cookie = `${CONSENT_COOKIE}=${value}; path=/; max-age=${CONSENT_MAX_AGE}; SameSite=Lax`;
}

